"""First-launch instructions for the office and sellers, with an acceptance scenario."""
from guide_layout import Guide, MUTED

g=Guide('Srez_first_launch_office.pdf','Первый запуск · видеоконтроль',4)
t=g.start('Перед первым рабочим днём')
